<?php
declare(strict_types=1);
require __DIR__.'/../api/config.php';
require __DIR__.'/includes/storage.php';
$u=usuarioAtual();
if(!$u){header('Location: ../login.php');exit;}
$p=strtolower((string)($u['perfil']??$u['role']??$u['nivel']??''));
$admin=!empty($u['is_admin'])||!empty($u['admin'])||$p==='admin'||strtolower((string)($u['login']??''))==='admin';
if(!$admin){http_response_code(403);exit('Acesso restrito ao administrador.');}
$f=orcamentosStorage().'/logs/processamentos.jsonl';$rows=[];
if(is_file($f)){foreach(array_reverse(file($f,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[]) as $line){$x=json_decode($line,true);if(is_array($x))$rows[]=$x;if(count($rows)>=500)break;}}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function monitorTs($v): int {$v=trim((string)$v);foreach(['!d/m/Y H:i:s','!d/m/Y H:i','!Y-m-d H:i:s','!Y-m-d\\TH:i:s'] as $fmt){$dt=DateTime::createFromFormat($fmt,$v);if($dt instanceof DateTime)return $dt->getTimestamp();}$ts=strtotime($v);return $ts===false?0:$ts;}
$q=trim((string)($_GET['q']??''));$status=trim((string)($_GET['status']??''));$de=trim((string)($_GET['de']??''));$ate=trim((string)($_GET['ate']??''));
$deTs=$de!==''?strtotime($de.' 00:00:00'):false;$ateTs=$ate!==''?strtotime($ate.' 23:59:59'):false;
$filtrados=array_values(array_filter($rows,function($r)use($q,$status,$deTs,$ateTs){$st=strtoupper((string)($r['status']??'ERRO'));if($status!==''&&$st!==$status)return false;$hay=mb_strtolower((string)($r['locatario']??'').' '.(string)($r['usuario']??'').' '.(string)($r['message']??'').' '.(string)($r['error']??''),'UTF-8');if($q!==''&&!str_contains($hay,mb_strtolower($q,'UTF-8')))return false;$ts=monitorTs($r['created_at']??'');if($deTs!==false&&$ts<$deTs)return false;if($ateTs!==false&&$ts>$ateTs)return false;return true;}));
$total=count($rows);$ok=count(array_filter($rows,fn($r)=>strtoupper((string)($r['status']??''))==='OK'));$falhas=count(array_filter($rows,fn($r)=>strtoupper((string)($r['status']??''))!=='OK'));$media=$total?array_sum(array_map(fn($r)=>(int)($r['duration_ms']??0),$rows))/$total:0;
?><?php $menuPage='monitoramento'; ?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Monitoramento</title><link rel="stylesheet" href="../assets/css/orcamentos/monitoramento.css"></head><body><?php require __DIR__ . '/includes/nav.php'; ?>
<main class="wrap"><header class="top"><div><span class="eyebrow">ADMINISTRAÇÃO DO SISTEMA</span><h1>Monitoramento</h1><p class="subtitle">Acompanhe o desempenho e o resultado das execuções do gerador de orçamentos.</p></div><div class="live-indicator"><span></span>Registros recentes</div></header>
<section class="stats" aria-label="Resumo dos processamentos"><article class="stat"><span class="stat-label">Processamentos registrados</span><strong><?=number_format($total,0,',','.')?></strong><small>Últimos 500 registros disponíveis</small></article><article class="stat success"><span class="stat-label">Concluídos</span><strong><?=number_format($ok,0,',','.')?></strong><small>Execuções com status OK</small></article><article class="stat failure"><span class="stat-label">Falhas</span><strong><?=number_format($falhas,0,',','.')?></strong><small>Execuções que exigem atenção</small></article><article class="stat"><span class="stat-label">Tempo médio</span><strong><?=number_format($media/1000,2,',','.')?> <em>s</em></strong><small>Tempo médio de processamento</small></article></section>
<form class="filters" method="get" action="monitoramento.php"><div class="filter-search"><label for="q">Pesquisar</label><input id="q" name="q" type="search" value="<?=h($q)?>" placeholder="Locatário, usuário ou mensagem"></div><div><label for="status">Status</label><select id="status" name="status"><option value="">Todos os status</option><option value="OK" <?=$status==='OK'?'selected':''?>>Concluído</option><option value="ERRO" <?=$status==='ERRO'?'selected':''?>>Falha</option></select></div><div><label for="de">Data inicial</label><input id="de" name="de" type="date" value="<?=h($de)?>"></div><div><label for="ate">Data final</label><input id="ate" name="ate" type="date" value="<?=h($ate)?>"></div><div class="filter-actions"><button class="btn primary" type="submit">Filtrar</button><a class="btn" href="monitoramento.php">Limpar</a></div></form>
<section class="table-wrap"><div class="table-heading"><div><h2>Execuções recentes</h2><p>Exibindo <?=count($filtrados)?> de <?=$total?> registros carregados</p></div></div><div class="table-scroll"><table><thead><tr><th>Data</th><th>Locatário / usuário</th><th>Status</th><th>Duração</th><th>Detalhes</th></tr></thead><tbody><?php foreach(array_slice($filtrados,0,200) as $r):$st=strtoupper((string)($r['status']??'ERRO'));?><tr><td class="date-cell"><?=h($r['created_at']??'—')?></td><td><strong><?=h($r['locatario']??'—')?></strong><span class="secondary-line"><?=h($r['usuario']??'Usuário não informado')?></span></td><td><span class="status <?= $st==='OK'?'status-ok':'status-error' ?>"><?= $st==='OK'?'Concluído':h($st) ?></span></td><td class="duration"><?=number_format(((int)($r['duration_ms']??0))/1000,2,',','.')?> s</td><td class="details"><?=h($r['message']??$r['error']??'Sem detalhes adicionais')?></td></tr><?php endforeach;?><?php if(!$filtrados):?><tr><td colspan="5"><div class="empty"><strong>Nenhum processamento encontrado</strong><span>Ajuste os filtros ou limpe a pesquisa.</span></div></td></tr><?php endif;?></tbody></table></div><?php if(count($filtrados)>200):?><div class="table-note">Exibindo os 200 registros mais recentes correspondentes aos filtros.</div><?php endif;?></section></main></body></html>